            case 4:
                // Chama o menu de administração
                if (email.equals(ADMIN_EMAIL)) {
                    showAdminMenu();
                } else {
                    JOptionPane.showMessageDialog(null, "Você não tem permissão de acesso a essa seção.");
                }
                break;
            default:
                JOptionPane.showMessageDialog(null, "Opção inválida!");
                showMenuApp(email);
                break;
        }
    }

    // --- Fluxo de Login ---
    public void readUserInputLogin(String option) throws LoginInvalidException, InfraException {
        try {
            userManager = new UserManager();
        } catch (InfraException e) {
            JOptionPane.showMessageDialog(null, e.getMessage());
            return;
        }

        int choice = Integer.parseInt(option);
        switch (choice) {

            case 1:
                registerUser();
                showMenuLogin();
                break;

            case 2: 
                loginUser();
                break;

            case 3: 
                System.exit(0);
                break;

            default:
                JOptionPane.showMessageDialog(null, "Opção inválida!");
                showMenuLogin();
                break;
        }
    }

    // --- LÓGICA DE LOGIN E ADMIN ---
    private void loginUser() throws LoginInvalidException, InfraException{
        boolean loggedIn = false;

        while (!loggedIn) {
            String email = JOptionPane.showInputDialog("Email do usuario:");
            if (email == null) { showMenuLogin(); return; }

            String password = JOptionPane.showInputDialog("Senha do usuario:");
            if (password == null) { showMenuLogin(); return; }

            loggedIn = loginValidator.checkUserLogin(email,password);

            if (loggedIn) {
                JOptionPane.showMessageDialog(null, "Login bem-sucedido!");

                // 1. Inicializa Managers (se o login for bem-sucedido)
                try {
                    cursoManager = new CursoManager();
                    questionarioManager = new QuestionarioManager();
                } catch (InfraException e) {
                    JOptionPane.showMessageDialog(null, "Erro ao inicializar dados. Contate o administrador.");
                    System.exit(1);
                    return;
                }

                // 2. VERIFICA SE É ADMINISTRADOR
                if (email.equalsIgnoreCase(ADMIN_EMAIL) && password.equalsIgnoreCase(ADMIN_PASSWORD)) {
                    JOptionPane.showMessageDialog(null, "Bem-vindo, Administrador!");
                    showAdminMenu();
                } else {
                    showMenuApp(email);
