    // --- NOVO FLUXO: ADMIN ---
    private void showAdminMenu() {
        String option = JOptionPane.showInputDialog("MENU ADMINISTRATIVO\n1-Gerenciar Cursos\n2-Gerenciar Questões\n3-Sair do Admin\n4-Deslogar e Voltar ao Menu Padrão","Admin Opção");

