        }

        switch (choice) {
            case 1:
                showCursoMenu();
                break;
            case 2:
                showQuestionarioMenu();
                break;
            case 3:
                // Limpar referências e voltar ao menu principal
                cursoManager = null;
                questionarioManager = null;
                showMenuLogin();
                break;
            case 4:
                cursoManager = null;
                questionarioManager = null;
                showMenuLogin();
                break;
            default:
                JOptionPane.showMessageDialog(null, "Opção inválida no Menu Admin!");
                showAdminMenu();
        }
    }

    private void showCursoMenu() {
