                removerCursoAdmin();
                break;
            case 4:
                showAdminMenu();
                break;
            default:
                JOptionPane.showMessageDialog(null, "Opção inválida no Menu Curso!");
                showCursoMenu();
        }
    }

    private void showQuestionarioMenu() {
        String option = JOptionPane.showInputDialog("GERENCIAMENTO DE QUESTÕES\n1-Adicionar Questão\n2-Visualizar Questões\n3-Remover Questão\n4-Voltar ao Admin Menu","Questão Opção");

        int choice = 0;
