                viewCursos();
                break;
            case 2:
                // Conecta com o teste vocacional
                Testes.questionario(email);
                break;
            case 3:
                System.exit(0);
                break;
            case 4:
                // Chama o menu de administração
                if (email.equals(ADMIN_EMAIL)) {
                    showAdminMenu();
                } else {
                    JOptionPane.showMessageDialog(null, "Você não tem permissão de acesso a essa seção.");
