package view;

import infra.InfraException;
import util.EmailInvalidException;
import util.LoginInvalidException;
import util.PasswordInvalidException;
import util.LoginValidator;
import javax.swing.JOptionPane;
import business.control.UserManager;
import testes.Testes;
import cursos.Cursos;

public class TelaUsuario {
    private UserManager userManager;
    private static TelaUsuario instance = null;
    private LoginValidator loginValidator;

    private TelaUsuario() throws InfraException{
        this.loginValidator = new LoginValidator();
    }


    public static void main (String[] args) throws LoginInvalidException, InfraException {
        showMenuLogin();
    }

    public static void showMenuLogin() throws LoginInvalidException, InfraException {
        // Mostra o menu inicial para o usuário

        TelaUsuario main = getInstance();

        String option = JOptionPane.showInputDialog("Olá usuário, bem vindo ao SouUFPB\nEscolha a opcao desejada:\n1-Se cadastrar\n2-Logar\n3-Sair","Sua opcao");     

        main.readUserInputLogin(option);
    }

    public static void showMenuApp(String email) throws InfraException {
        // Mostra o segundo menu para o usuário
        String option = JOptionPane.showInputDialog("Escolha a opcao desejada:\n1-Ver os Cursos da UFPB\n2-Fazer teste vocacional\n3-Sair","Sua opcao");

        TelaUsuario secondmain = new TelaUsuario();

        secondmain.readUserInputApp(option, email);
    }

    private void readUserInputApp(String option, String email) throws InfraException {
        // Lê a opção do usuário no segundo menu
        int choice = Integer.parseInt(option);
        switch (choice) {
            case 1:
                // Implementar visualização dos cursos da UFPB
                Cursos.entraremcursos();
                break;
            case 2:
                // Conecta com o teste vocacional
                Testes.questionario(email);
                break;
            case 3:
                // Implementar a saída
                System.exit(0);
                break;
            default:
                // Implementar opção inválida
                JOptionPane.showMessageDialog(null, "Opção inválida!");
                showMenuApp(email);
                break;
        }
    }

    public void readUserInputLogin(String option) throws LoginInvalidException, InfraException {
        try {
            userManager = new UserManager();
        } catch (InfraException e) {
            String option2 = JOptionPane.showInputDialog(e.getMessage());
        }
        int choice = Integer.parseInt(option);
        switch (choice) {

            case 1:
                // Realiza cadastro de usuário
                registerUser();
                showMenuLogin();
                break;

            case 2: 
                // Realiza login de usuário
                loginUser();
                break;

            case 3: 
                // Encerra a aplicação
                System.exit(0);
                break;

            default:
                JOptionPane.showMessageDialog(null, "Opção inválida!");
                showMenuLogin();
                break;
        }
    }

    private void registerUser() {
        // Implementa o registro do usuário
        // Continua pedindo as informações até que todas estejam corretas
        while (true) {
            String name = JOptionPane.showInputDialog("Nome do usuario:");
            if (name == null) {
                break;
            }

            String email = JOptionPane.showInputDialog("Email do usuario:");
            if (email == null) {
                break;
            }

            String pass = JOptionPane.showInputDialog("Senha do usuario:");
            if (pass == null) {
                break;
            }

            try {
                String[] args = {name, email, pass};
                this.userManager.addUser(args);
                JOptionPane.showMessageDialog(null, "Usuario adicionado com sucesso!");
                break;
            } catch (LoginInvalidException | EmailInvalidException | PasswordInvalidException e) {
                JOptionPane.showMessageDialog(null, e.getMessage());
            } catch (Exception e) {
                JOptionPane.showMessageDialog(null, "Erro desconhecido: " + e.getMessage());
            }
        }
    }

    private void loginUser() throws LoginInvalidException, InfraException{
        // Implementa o login do usuário
        boolean loggedIn = false;

        while (!loggedIn) {
            String email = JOptionPane.showInputDialog("Email do usuario:");
            if (email == null) {
                showMenuLogin();
                return;
            }

            String password = JOptionPane.showInputDialog("Senha do usuario:");
            if (password == null) {
                showMenuLogin();
                return;
            }

            loggedIn = loginValidator.checkUserLogin(email,password);

            if (loggedIn) {
                JOptionPane.showMessageDialog(null, "Login bem-sucedido!");
                showMenuApp(email);
            } else {
                JOptionPane.showMessageDialog(null, "Email ou senha incorretos. Por favor, tente novamente.");
            }
        }
    }

    public static TelaUsuario getInstance() throws InfraException{

        if(instance == null){
            instance = new TelaUsuario();
        }

        return instance;
    }

}


package business.control;

// Importando as classes necessárias
import infra.InfraException;
import infra.CursoFile;
import business.model.Curso;
import java.util.Map;
import java.util.logging.Logger;

// Definindo a classe CursoManager
public class CursoManager {
    // Inicializando um Map para armazenar os cursos e uma instância da classe CursoFile
    private Map<String, Curso> cursos;
    private CursoFile cursoFile;

    // Construtor da classe que lança uma exceção do tipo InfraException
    public CursoManager() throws InfraException{
        // Instanciando um novo CursoFile e carregando os cursos do arquivo
        cursoFile = new CursoFile();
        cursos = cursoFile.carregarCursos();
    }

    // Método para adicionar um curso
    public void adicionarCurso(String[] args){
        // Adicionando um novo Curso no Map 'cursos' e salvando no arquivo
        cursos.put(args[0], new Curso(args[0], args[1], args[2]));
        cursoFile.salvarCursos(cursos);
    }

    // Método para remover um curso
    public void removerCurso(String nome) throws InfraException{
        // Verifica se o curso existe no Map antes de tentar remover
        if(!cursos.containsKey(nome)){
            throw new IllegalArgumentException("Curso não encontrado. Tente novamente.");
        }

        // Remove o curso do Map 'cursos' e salva no arquivo
        cursos.remove(nome);
        cursoFile.salvarCursos(cursos);
    }

    // Método para retornar os cursos
    public Map<String,Curso> getCursos() throws InfraException{
        Logger logger = cursoFile.getLogger();

        try{
            // Carrega os cursos do arquivo
            Map<String,Curso> meusCursos = cursoFile.carregarCursos();
            return meusCursos;

        } catch(NullPointerException ex){
            // Registra a exceção e lança uma nova InfraException
            logger.severe(ex.getMessage());
            throw new InfraException("Erro na exibição. Contate o admnistrador ou tente mais tarde.");
        }
    }
}

package business.control;

import infra.InfraException;
import infra.QuestionarioFile;
import business.model.Questionario;
import java.util.Map;
import java.util.logging.Logger;

public class QuestionarioManager {
    private Map<String, Questionario> questionarios;
    private QuestionarioFile questionarioFile;

    public QuestionarioManager() throws InfraException{
        questionarioFile = new QuestionarioFile();
        questionarios = questionarioFile.carregarQuestionarios();
    }

    public void adicionarQuestionario(String pergunta, String area){
        questionarios.put(pergunta, new Questionario(pergunta, area));
        questionarioFile.salvarQuestionarios(questionarios);
    }

    public void removerQuestionario(String pergunta) throws InfraException{
        if(!questionarios.containsKey(pergunta)){
            throw new IllegalArgumentException("Pergunta não encontrada. Tente novamente.");
        }

        questionarios.remove(pergunta);
        questionarioFile.salvarQuestionarios(questionarios);
    }

    public Map<String,Questionario> getQuestionarios() throws InfraException{
        Logger logger = questionarioFile.getLogger();

        try{
            Map<String,Questionario> meusQuestionarios = questionarioFile.carregarQuestionarios();
            return meusQuestionarios;

        } catch(NullPointerException ex){
            logger.severe(ex.getMessage());
            throw new InfraException("Erro na exibição. Contate o administrador ou tente mais tarde.");
        }
    }
}



